#!/usr/bin/env bash
# ==========================================================================
#  FIRONOVA — Courriels NOVA bilingues
#  Remplace les anciens templates (noir/rouge, anglais) par un shell NOVA
#  bilingue FR/EN (selon order['lang']) avec adresse, suivi, rabais, RUO.
#  Idempotent. Lancer depuis /app :  bash install_emails_nova.sh
# ==========================================================================
set -euo pipefail
SERVER="backend/server.py"
[ -f "$SERVER" ] || { echo "ERREUR: lance depuis /app (backend/server.py introuvable)"; exit 1; }

if grep -q "_email_shell" "$SERVER"; then
  echo "→ Courriels NOVA déjà installés. Rien à faire."
  exit 0
fi

TS=$(date +%Y%m%d_%H%M%S)
cp "$SERVER" "${SERVER}.bak_emails_${TS}"
echo "→ Sauvegarde : ${SERVER}.bak_emails_${TS}"

cat > /tmp/_emails_b64.txt <<'B64EOF'

B64EOF

python3 - <<'PYEOF'
import base64, ast
SERVER="backend/server.py"
src=open(SERVER).read()
BLOCK=base64.b64decode(open('/tmp/_emails_b64.txt').read()).decode()

i1=src.index("def _items_html(")
i3=src.index("async def _send_email(")
new_src=src[:i1]+BLOCK.rstrip()+"\n\n\n"+src[i3:]

repl=[
 ('html = _order_email_html(order, "Order received")',
  'html = _order_email_html(order, body_intro_fr="Commande reçue", body_intro_en="Order received")'),
 ('admin_html = _order_email_html(order, "New order received")',
  'admin_html = _order_email_html(order, body_intro_fr="Nouvelle commande", body_intro_en="New order received")'),
 ('html = _order_email_html(order, "Payment received")',
  'html = _order_email_html(order, body_intro_fr="Paiement reçu", body_intro_en="Payment received")'),
 ('heading = "Payment received" if order.get("payment_status") == "paid" else "Order received"\n    html = _order_email_html(order, heading)',
  'if order.get("payment_status") == "paid":\n        html = _order_email_html(order, body_intro_fr="Paiement reçu", body_intro_en="Payment received")\n    else:\n        html = _order_email_html(order, body_intro_fr="Commande reçue", body_intro_en="Order received")'),
]
for old,new in repl:
    assert old in new_src, "appel introuvable: "+old[:40]
    new_src=new_src.replace(old,new)

ast.parse(new_src)
open(SERVER,"w").write(new_src)
print("→ server.py patché — AST OK")
PYEOF

rm -f /tmp/_emails_b64.txt
echo ""
echo "✓ Courriels NOVA bilingues installés."
echo "  Les courriels de commande/paiement s'affichent maintenant :"
echo "    · aux couleurs NOVA (Nordfjord Blue + Nova Cyan)"
echo "    · en FR ou EN selon la langue de la commande"
echo "    · avec adresse de livraison, rabais, bouton de suivi, mention RUO"
echo "  Redémarre le backend pour activer."
